<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {ElMessage} from 'element-plus'
import {api,post,formatDate} from '../api'
import type {Material,Ticket} from '../types'
import type {Evaluation} from '../types'
import EvaluationReport from './EvaluationReport.vue'
import V19Report from './V19Report.vue'
type Job={id:string;title:string;project_id:string;outcome_id:string;status:string;revision:number;error:string;created_at:string}
type ScopeOption={id:string;title:string;parent_id:string;parent_title:string}
type Boundary={project_start_date:string;review_cutoff:string;cutoff_basis:string}
type Detail=Job & {stages:Record<string,{status:string;attempts:number;error?:string;output?:string;execution_mode?:string}>; waiting:Record<string,{message:string;details:unknown}>;files:{path:string;size:number}[];input_summary:Record<string,string>;scope_options?:ScopeOption[];scope_evidence?:{id:string;locator:string;quote:string;kind:string}[];canonical_name?:string;search_mode?:string;search_boundary?:Boundary|null;scope_mapping?:{frozen_child_id?:string;evidence_routes?:Record<string,string[]>;review_note?:string}|null}
const labels:Record<string,string>={wu_intake:'① 吴老师：成果定位与建卡',search_replay:'② Search：证据检索与时间核验',attribution:'③ 原版AI贡献归因',wu_evaluation:'④ 吴老师：成果评价',v19_evaluation:'⑤ v19：双层评估',export:'⑥ 两套结果分别导出'}
const statuses:Record<string,string>={queued:'排队中',pending:'未开始',running:'执行中',waiting:'待补充 / 待确认',failed:'失败',succeeded:'已完成',cancelled:'已取消'}
const jobs=ref<Job[]>([]),materials=ref<Material[]>([]),detail=ref<Detail|null>(null),open=ref(false),busy=ref(false),error=ref('')
const title=ref(''),projectId=ref(''),projectName=ref(''),outcomeId=ref(''),materialIds=ref<string[]>([]),scope=ref('')
const tickets=ref<Ticket[]>([]),ticketId=ref('')
const searchMode=ref('live'),startDate=ref(''),cutoffDate=ref(''),cutoffBasis=ref('')
const search=ref<unknown|null>(null),workspace=ref<unknown|null>(null),mappingName=ref(''),mappingReviewed=ref(false)
const amendScope=ref(''),amendMaterials=ref<string[]>([]),amendSearch=ref<unknown|null>(null),amendWorkspace=ref<unknown|null>(null),amendMapping=ref(''),amendReviewed=ref(false)
const amendMode=ref('live'),amendStart=ref(''),amendCutoff=ref(''),amendBasis=ref(''),amendChild=ref(''),amendReviewNote=ref('')
const dimensionNames:Record<string,string>={D1:'问题解决与先进性',D2:'原创与项目新增',D3:'学术影响',D4:'开放复用',D5:'真实应用',D6:'主线集成',D7:'外部认可'}
const amendRoutes=ref<Record<string,string[]>>(Object.fromEntries(Object.keys(dimensionNames).map(k=>[k,[]])))
function childOptions(value:unknown):ScopeOption[]{const w=value as any;const parents=w?.step3_frozen_outcomes?.outcomes;if(!Array.isArray(parents))return [];return parents.flatMap(p=>Array.isArray(p?.child_outcomes)?p.child_outcomes.filter((c:any)=>c?.outcome_id).map((c:any)=>({id:String(c.outcome_id),title:String(c.title||''),parent_id:String(p.outcome_id||''),parent_title:String(p.title||'')})):[])}
const scopeChoices=computed(()=>amendWorkspace.value?childOptions(amendWorkspace.value):detail.value?.scope_options||[])
function activateMapping(){if(!amendMapping.value)amendMapping.value=detail.value?.canonical_name||detail.value?.input_summary.confirmed_scope||''}
let timer:ReturnType<typeof setInterval>|undefined
const reportPreview=ref<Evaluation|null>(null),reportOpen=ref(false)
const v19Preview=ref<any>(null),v19Open=ref(false)
async function showV19(){if(!detail.value?.stages.v19_evaluation.output)return;await action(async()=>{const path=detail.value!.stages.v19_evaluation.output!;const data=await api<{result:any}>(`/admin/pipelines/${detail.value!.id}/artifact?path=${encodeURIComponent(path)}`);v19Preview.value=data.result;v19Open.value=true})}
async function saveReportDraft(){if(!detail.value)return;await action(async()=>{await post(`/admin/pipeline-reports/${detail.value!.id}/draft`);ElMessage.success('吴老师报告已转入结果与审核，尚未发布')})}
async function showReport(){if(!detail.value)return;await action(async()=>{const r=await api<{payload:Evaluation}>(`/admin/pipeline-reports/${detail.value!.id}`);reportPreview.value=r.payload;reportOpen.value=true})}
async function load(){try{[jobs.value,materials.value,tickets.value]=await Promise.all([api<Job[]>('/admin/pipelines'),api<Material[]>('/admin/materials'),api<Ticket[]>('/admin/tickets')]);if(detail.value && open.value)detail.value=await api(`/admin/pipelines/${detail.value.id}`);error.value=''}catch(e){error.value=(e as Error).message}}
async function chooseTicket(){if(!ticketId.value)return;await action(async()=>{const t=tickets.value.find(t=>t.id===ticketId.value);if(t)title.value=t.query;const s=await api<{payload:{project_name:string;project_start_date:string|null;review_cutoff:string|null;cutoff_basis:string};material_ids:string[]}|null>(`/admin/submissions/${ticketId.value}`);if(s){projectName.value=s.payload.project_name;materialIds.value=s.material_ids;startDate.value=s.payload.project_start_date||'';cutoffDate.value=s.payload.review_cutoff||'';cutoffBasis.value=s.payload.cutoff_basis;searchMode.value='live'}projectId.value='';outcomeId.value='';scope.value='';workspace.value=null;search.value=null;mappingName.value='';mappingReviewed.value=false})}
onMounted(async()=>{await load();timer=setInterval(load,4000);const target=new URLSearchParams(window.location.search).get('pipeline');const job=jobs.value.find(j=>j.id===target);if(job)await inspect(job)});onUnmounted(()=>clearInterval(timer))
async function action(fn:()=>Promise<void>){busy.value=true;try{await fn();await load()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function jsonFile(event:Event,kind:string){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(file.size>6*1024*1024)throw new Error('JSON文件不能超过6MB');const data=JSON.parse(await file.text());if(kind==='search')search.value=data;else if(kind==='workspace')workspace.value=data;else if(kind==='amendSearch'){amendSearch.value=data;amendMode.value='replay';}else amendWorkspace.value=data;ElMessage.success('JSON已读取，提交时将检查项目与成果对应关系')}catch(e){ElMessage.error((e as Error).message);input.value=''}}
async function create(){await action(async()=>{await post('/admin/pipelines',{ticket_id:ticketId.value||null,title:title.value,project_id:projectId.value,project_name:projectName.value,outcome_id:outcomeId.value,material_ids:materialIds.value,confirmed_scope:scope.value,search_mode:searchMode.value,search_boundary:startDate.value&&cutoffDate.value?{project_start_date:startDate.value,review_cutoff:cutoffDate.value,cutoff_basis:cutoffBasis.value}:null,search_replay:searchMode.value==='replay'?search.value:null,v19_workspace:workspace.value,v19_scope_mapping:mappingName.value?{outcome_id:outcomeId.value,canonical_name:mappingName.value,reviewed:mappingReviewed.value}:null});ElMessage.success('工作流已排队');title.value='';materialIds.value=[]})}
async function inspect(job:Job){await action(async()=>{const d=await api<Detail>(`/admin/pipelines/${job.id}`);detail.value=d;amendScope.value='';amendMaterials.value=[];amendSearch.value=null;amendWorkspace.value=null;amendMapping.value='';amendReviewed.value=false;amendMode.value=d.search_mode||'replay';amendStart.value=d.search_boundary?.project_start_date||'';amendCutoff.value=d.search_boundary?.review_cutoff||'';amendBasis.value=d.search_boundary?.cutoff_basis||'';amendChild.value=d.scope_mapping?.frozen_child_id||'';amendReviewNote.value=d.scope_mapping?.review_note||'';amendRoutes.value=Object.fromEntries(Object.keys(dimensionNames).map(k=>[k,[...(d.scope_mapping?.evidence_routes?.[k]||[])]]));open.value=true})}
async function amend(){if(!detail.value)return;await action(async()=>{const d=detail.value!;const patch:Record<string,unknown>={revision:d.revision};if(amendScope.value)patch.confirmed_scope=amendScope.value;if(amendMaterials.value.length)patch.material_ids=amendMaterials.value;if(amendSearch.value)patch.search_replay=amendSearch.value;if(amendWorkspace.value)patch.v19_workspace=amendWorkspace.value;if(amendMode.value!==(d.search_mode||'replay'))patch.search_mode=amendMode.value;if(amendMode.value==='live'&&(amendStart.value!==(d.search_boundary?.project_start_date||'')||amendCutoff.value!==(d.search_boundary?.review_cutoff||'')||amendBasis.value!==(d.search_boundary?.cutoff_basis||''))){if(!amendStart.value||!amendCutoff.value||!amendBasis.value.trim())throw new Error('请完整填写启动日期、评审截止日和日期来源');patch.search_boundary={project_start_date:amendStart.value,review_cutoff:amendCutoff.value,cutoff_basis:amendBasis.value}}if(amendMapping.value){if(amendChild.value&&!amendReviewNote.value.trim())throw new Error('请说明子成果范围及路由审查依据');const known=new Set((d.scope_evidence||[]).map(e=>e.id));if(amendChild.value&&Object.values(amendRoutes.value).flat().some(id=>!known.has(id)))throw new Error('路由中存在已失效的证据，请根据当前材料重新选择');patch.v19_scope_mapping={outcome_id:d.outcome_id,canonical_name:amendMapping.value,reviewed:amendReviewed.value,frozen_child_id:amendChild.value||null,evidence_routes:amendChild.value?amendRoutes.value:null,review_note:amendReviewNote.value}}await api(`/admin/pipelines/${d.id}`,{method:'PATCH',body:JSON.stringify(patch)});ElMessage.success('补充已保存，受影响阶段将重新执行')})}
function download(path:string){return `/api/admin/pipelines/${detail.value?.id}/artifact?path=${encodeURIComponent(path)}`}
</script>
<template><section class="pipeline-workbench"><el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <el-collapse><el-collapse-item title="新建评价工作流" name="create"><el-form class="panel padded" label-position="top" @submit.prevent="create"><div class="pipeline-form-grid"><el-form-item label="关联用户成果工单"><el-select v-model="ticketId" clearable placeholder="选择待受理工单，自动带入表单和材料" @change="chooseTicket"><el-option v-for="t in tickets.filter(t=>t.status==='pending')" :key="t.id" :value="t.id" :label="t.query"/></el-select></el-form-item>
    <el-form-item label="成果名称"><el-input v-model="title" aria-label="工作流成果名称" maxlength="200"/></el-form-item>
    <el-form-item label="项目名称"><el-input v-model="projectName" aria-label="工作流项目名称" maxlength="300"/></el-form-item>
    <el-form-item label="项目ID（与Search、v19一致）"><el-input v-model="projectId" aria-label="工作流项目ID" maxlength="100"/></el-form-item>
    <el-form-item label="冻结成果ID（与Search、v19一致）"><el-input v-model="outcomeId" aria-label="工作流成果ID" maxlength="160"/></el-form-item>
    <el-form-item label="选择已上传项目材料"><el-select v-model="materialIds" multiple class="full-width" data-testid="pipeline-materials"><el-option v-for="m in materials.filter(m=>(m.purpose||'project')==='project')" :key="m.id" :value="m.id" :label="m.filename"/></el-select></el-form-item>
    <el-form-item label="已确认的成果范围（可选）"><el-input v-model="scope" aria-label="已确认范围" maxlength="200"/></el-form-item>
    <el-form-item label="Search执行方式"><el-select v-model="searchMode" aria-label="Search执行方式"><el-option label="历史结果回放" value="replay"/><el-option label="实际联网Search（五模块）" value="live"/></el-select></el-form-item><el-form-item v-if="searchMode==='live'" label="项目正式启动日期"><input type="date" v-model="startDate" aria-label="项目正式启动日期"/></el-form-item><el-form-item v-if="searchMode==='live'" label="阶段评审截止日期"><input type="date" v-model="cutoffDate" aria-label="阶段评审截止日期"/></el-form-item><el-form-item v-if="searchMode==='live'" label="日期依据"><el-input v-model="cutoffBasis" placeholder="报告页码、统计截止说明或阶段表"/></el-form-item><el-form-item v-if="searchMode==='replay'" label="历史Search回放包（可后补）"><input type="file" accept=".json" aria-label="Search回放JSON" @change="jsonFile($event,'search')"/></el-form-item>
    <el-form-item label="v19工作区JSON（可后补）"><input type="file" accept=".json" aria-label="v19工作区JSON" @change="jsonFile($event,'workspace')"/></el-form-item>
    <el-form-item label="v19对应的吴老师规范成果名（可后补）"><el-input v-model="mappingName" aria-label="规范成果映射名称" maxlength="200"/></el-form-item>
    <el-form-item label="成果范围对应关系"><el-checkbox v-model="mappingReviewed">已审查：该具体成果确实对应上述v19冻结成果</el-checkbox></el-form-item>
  </div><p class="muted">缺失材料或范围有歧义时会停在待补充状态；不能只按名字相近强行对应。项目材料可在“材料库”上传。</p><el-button native-type="submit" type="primary" :loading="busy" :disabled="!title.trim()||!projectName.trim()||!projectId.trim()||!outcomeId.trim()||!materialIds.length">创建完整工作流</el-button></el-form></el-collapse-item></el-collapse>
  <div class="panel padded"><div class="section-heading"><h2>工作流任务</h2><el-button @click="load">刷新工作流</el-button></div><el-table :data="jobs" empty-text="尚无完整工作流"><el-table-column prop="title" label="成果" min-width="180"/><el-table-column prop="project_id" label="项目" width="110"/><el-table-column label="状态" min-width="150"><template #default="{row}"><el-tag :type="row.status==='failed'?'danger':row.status==='waiting'?'warning':row.status==='succeeded'?'success':'info'">{{statuses[row.status]}}</el-tag></template></el-table-column><el-table-column prop="error" label="当前事项" min-width="220"/><el-table-column label="创建时间" min-width="180"><template #default="{row}">{{formatDate(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="125"><template #default="{row}"><el-button type="primary" link @click="inspect(row)">查看工作流</el-button></template></el-table-column></el-table></div>
  <el-dialog v-model="open" title="完整评价工作流" width="min(1100px,96vw)"><template v-if="detail"><h2>{{detail.title}}</h2><p class="muted">{{detail.project_id}} / {{detail.outcome_id}} · {{statuses[detail.status]}} · 版本 {{detail.revision}}</p><div class="pipeline-stages"><div v-for="(name,id) in labels" :key="id" class="panel padded"><strong>{{name}}</strong><p>{{statuses[detail.stages[id]?.status]}} · 执行 {{detail.stages[id]?.attempts}} 次</p><p v-if="detail.stages[id]?.execution_mode==='verified_external_run'" class="muted">独立执行后回挂，已核对同一上游材料和结果哈希</p><p v-if="detail.stages[id]?.error" class="stage-error">{{detail.stages[id]?.error}}</p><el-collapse v-if="detail.waiting[id]"><el-collapse-item title="查看待确认详情"><pre class="material-text">{{JSON.stringify(detail.waiting[id].details,null,2)}}</pre></el-collapse-item></el-collapse></div></div>
<div class="task-draft-actions">    <el-button v-if="detail.stages.wu_evaluation?.status==='succeeded'" type="primary" @click="showReport">预览吴老师报告</el-button><el-button v-if="detail.stages.wu_evaluation?.status==='succeeded'" @click="saveReportDraft">转入报告审核</el-button><el-button v-if="detail.stages.v19_evaluation?.status==='succeeded'" @click="showV19">预览v19独立底稿</el-button></div>
    <section v-if="['waiting','failed','succeeded'].includes(detail.status)" class="panel padded"><h3>补充信息后继续</h3><el-form label-position="top"><el-form-item label="确认规范成果名"><el-input v-model="amendScope" aria-label="补充确认成果名"/></el-form-item><el-form-item label="替换本次项目材料（可多选）"><el-select v-model="amendMaterials" multiple class="full-width"><el-option v-for="m in materials.filter(m=>(m.purpose||'project')==='project')" :key="m.id" :value="m.id" :label="m.filename"/></el-select></el-form-item><div class="pipeline-form-grid"><el-form-item label="检索方式"><el-select v-model="amendMode" aria-label="补充检索方式"><el-option label="本轮公开检索" value="live"/><el-option label="历史结果回放（非本次检索）" value="replay"/></el-select></el-form-item><template v-if="amendMode==='live'"><el-form-item label="项目启动日期"><input v-model="amendStart" type="date" aria-label="补充项目启动日期"/></el-form-item><el-form-item label="评审截止日期"><input v-model="amendCutoff" type="date" aria-label="补充评审截止日期"/></el-form-item><el-form-item label="日期来源"><el-input v-model="amendBasis" aria-label="补充日期来源" maxlength="1000"/></el-form-item></template><el-form-item v-if="amendMode==='replay'" label="补充Search回放JSON"><input type="file" accept=".json" @change="jsonFile($event,'amendSearch')"/></el-form-item><el-form-item label="补充v19工作区JSON"><input type="file" accept=".json" @change="jsonFile($event,'amendWorkspace')"/></el-form-item></div><el-form-item label="v19映射规范成果名"><el-input v-model="amendMapping"/></el-form-item><el-form-item label="单独评价的冻结子成果（主要成果整体评价可留空）"><el-select v-model="amendChild" clearable aria-label="冻结子成果" class="full-width" @change="activateMapping"><el-option v-for="o in scopeChoices" :key="o.id" :value="o.id" :label="`${o.parent_title} / ${o.title}（${o.id}）`"/></el-select></el-form-item><template v-if="amendChild"><p class="muted">请选择每个维度可以使用的证据。留空表示该维度没有已确认的路由，不会继承父项目其他成果的依据。</p><el-form-item v-for="(label,id) in dimensionNames" :key="id" :label="`${id} ${label}`"><el-select v-model="amendRoutes[id]" multiple class="full-width" :aria-label="`${id}证据路由`" @change="activateMapping"><el-option v-for="e in detail.scope_evidence||[]" :key="e.id" :value="e.id" :label="`${e.id} · ${e.locator} · ${e.quote.slice(0,55)}`"/></el-select></el-form-item><el-collapse><el-collapse-item title="查看本轮可引用的材料原文"><div v-for="e in detail.scope_evidence||[]" :key="e.id"><strong>{{e.id}} · {{e.kind}} · {{e.locator}}</strong><p>{{e.quote}}</p></div></el-collapse-item></el-collapse><el-form-item label="子成果范围与路由审查说明"><el-input v-model="amendReviewNote" type="textarea" :rows="3" aria-label="路由审查说明" @input="activateMapping"/></el-form-item></template><el-checkbox v-model="amendReviewed" @change="activateMapping">已核对上述成果对应关系及证据范围</el-checkbox><p class="muted">修改材料、成果范围或检索输入后，旧路由确认会失效，需依据新底稿重新核对。</p></el-form><div class="task-draft-actions"><el-button v-if="['waiting','failed'].includes(detail.status)" :disabled="busy" @click="action(async()=>{await post(`/admin/pipelines/${detail!.id}/resume`,{revision:detail!.revision})})">按原输入重试 / 续跑</el-button><el-button type="primary" :loading="busy" @click="amend">保存补充并续跑</el-button></div></section>
<h3 class="pipeline-files-title">阶段底稿与独立结果</h3><p class="muted">吴老师结果位于 wu_evaluation，双层结果位于 v19_evaluation；最终 export 分别保存两份JSON。</p><el-table :data="detail.files" max-height="360"><el-table-column prop="path" label="文件" min-width="300"/><el-table-column label="下载" width="90"><template #default="{row}"><a :href="download(row.path)" class="text-link">下载</a></template></el-table-column></el-table>
  </template></el-dialog>
<el-dialog v-model="reportOpen" title="吴老师成果报告 · 待审核" width="min(1300px,96vw)"><el-alert title="这是独立保存的吴老师报告草稿；v19状态另行查看，尚未发布到用户端。" type="info" :closable="false"/><EvaluationReport v-if="reportPreview" :value="reportPreview"/></el-dialog><el-dialog v-model="v19Open" title="v19双层评估 · 独立底稿" width="min(1200px,96vw)"><V19Report v-if="v19Preview" :value="v19Preview"/></el-dialog></section></template>
